from mk import *
STRICT["on"] = True
from lib import mini
import math
a = math.radians(55); vx = 11.5 * math.cos(a); vy = 11.5 * math.sin(a); tg = 11 / vx; yg = vy * tg - 5 * tg * tg

def fig():
    g = Fig(560, 360, "בעיטת פנדל: כדור במרחק d מקו השער נבעט במהירות v0 בזווית אלפא למגרש. ארבעה גרפים של הרכיב האנכי של המהירות, ומסלול פרבולי עם הנקודות P ו-Q")
    g.ground(20, 540, 150)
    g.rect(450, 70, 12, 80, fill="var(--d-fill)")
    g.line(450, 70, 520, 70, width=2); g.line(520, 70, 520, 150, width=2)
    g.path("M 100,145 Q 280,-30 455,110", stroke="var(--d-body)", width=2, dash="6 4")
    g.ball(100, 143, 7)
    g.arrow(106, 138, 146, 90, "v₀", lx=150, ly=86, anchor="start")
    g.angle(100, 143, 26, 0, 50, "α")
    g.dim(100, 150, 450, 150, "d", offset=-18, side=1)
    g.heb(456, 175, "קו השער")
    opts = [("1", [(0, 0.7), (1, -0.6)]), ("2", [(0, -0.5), (1, 0.6)]), ("3", [(0, 0.35), (1, 0.15)]), ("4", [(0, 0.8), (1, 0.35)])]
    for i, (lab, pts) in enumerate(reversed(opts)):
        mini(g, 40 + i * 70, 250, 50, 40, pts=pts, label=lab, yl="v_y", neg=True)
    X, Y = g.graph(330, 330, 190, 110, "x", "y", xmax=1, ymax=1, grid=False)
    g.curve(X, Y, lambda u: 4 * 0.92 * u * (1 - u), 0, 1)
    g.dot(X(0.2), Y(4 * 0.92 * 0.16)); g.text(X(0.2) - 8, Y(4 * 0.92 * 0.16) - 6, "P", anchor="end")
    g.dot(X(0.5), Y(0.92)); g.text(X(0.5), Y(0.92) - 10, "Q")
    return g

E(id="bagrut-2017-q1", year=2017, label="2017 שאלה 1", topic="kinematics", sub="kin-projectile", diff=3, fig=fig,
  stem=r"במשחק כדורגל שחקן עומד לבעוט בעיטת עונשין. כדי להטעות את השוער הוא מסתכל לאחת מפינות השער, אבל בועט במרכז השער. לשיטה הזו קוראים שיטת פננקה, על שם השחקן הצ'כי. אחרי הבעיטה הכדור נע במסלול של פרבולה, במישור שניצב למגרש, כך שההיטל של המסלול על המגרש ניצב לקו השער. נסמן: $d$ המרחק של הכדור מקו השער לפני הבעיטה, $v_0$ גודל המהירות ההתחלתית של הכדור, ו-$\alpha$ הזווית בין המהירות ההתחלתית למישור המגרש. התנגדות האוויר זניחה.",
  parts=[
    P("א", r"איזה מארבעת הגרפים 1-4 מתאר נכון את הרכיב האנכי של מהירות הכדור באוויר, כפונקציה של הזמן? נמקו.", choice(["1", "2", "3", "4"], 0), ["graph", "signs"], [
        X(r"בוחרים כלפי מעלה כחיובי. על הכדור פועל רק הכובד, ולכן התאוצה האנכית קבועה, ושלילית כי היא כלפי מטה."),
        S(r"משוואת המהירות בציר האנכי", r"הרכיב האנכי מתחיל חיובי. התאוצה היא תאוצת הכובד, ולכן מציבים אותה במקום התאוצה, עם מינוס", r"v_y = v_0\sin\alpha + (-g)\,t", eq=r"v = v_0 + at"),
        S(r"הגרף", r"זה קו ישר יורד, בשיפוע קבוע. הוא חוצה את ציר הזמן בשיא, וממשיך לערכים שליליים", r"\frac{\Delta v_y}{\Delta t} = -g"),
    ], r"גרף 1", key=r"גרף 1"),
    P("ב1", r"בתרשים 2 מוצג המסלול של כדור שנכנס לשער, ועליו הנקודות $P$ ו-$Q$. הנקודה $Q$ גבוהה מהנקודה $P$. האם גודל הרכיב האופקי של מהירות הכדור בנקודה $P$ קטן מזה שבנקודה $Q$, גדול ממנו או שווה לו? הסבירו.", choice(["קטן", "גדול", "שווה"], 2), ["principle"], [
        S(r"אין כוח אופקי", r"התנגדות האוויר זניחה, והכובד אנכי. לכן בציר האופקי אין תאוצה, והרכיב האופקי קבוע", r"a_x = 0 \;\Rightarrow\; \Delta v_x = 0"),
    ], r"שווה: הרכיב האופקי קבוע לאורך כל המסלול", key=r"הרכיב האופקי קבוע"),
    P("ב2", r"האם גודל התאוצה של הכדור בנקודה $P$ קטן מזה שבנקודה $Q$, גדול ממנו או שווה לו? הסבירו.", choice(["קטן", "גדול", "שווה"], 2), ["principle"], [
        S(r"הכוח היחיד", r"על הכדור פועל רק כוח הכובד, והוא קבוע לאורך כל המסלול. לכן גם התאוצה קבועה", r"\Sigma F = mg \;\Rightarrow\; a = g", eq=r"\Sigma\vec F = m\vec a"),
    ], r"שווה: בכל המסלול התאוצה היא $g$ כלפי מטה", key=r"גודל התאוצה לא משתנה"),
    P("ג", r"שחקן בעט בשיטת פננקה ממרחק $d = 11\,\text{m}$ מקו השער, במהירות שגודלה $v_0 = 11.5\,\text{m/s}$, בזווית $\alpha = 55^\circ$ מעל האופק. גובה השער $h = 2.44\,\text{m}$. באיזה גובה חוצה הכדור את קו השער? הראו שהכדור בוודאות נכנס לשער (בלי הפרעה, למשל של השוער). התייחסו לכדור כאל גוף נקודתי.", num(yg, "m"), ["principle", "algebra"], [
        X(r"בוחרים את כיוון הבעיטה כחיובי בציר האופקי, וכלפי מעלה כחיובי בציר האנכי. הראשית בנקודת הבעיטה."),
        S(r"רכיבי המהירות ההתחלתית", r"מפרקים את המהירות לפי הזווית", r"v_{0x} = 11.5\cos 55^\circ \approx 6.60\,\text{m/s},\qquad v_{0y} = 11.5\sin 55^\circ \approx 9.42\,\text{m/s}"),
        S(r"הזמן עד קו השער", r"בציר האופקי המהירות קבועה", r"11 = 0 + 6.60\,t \;\Rightarrow\; t = \frac{11}{6.60} \approx 1.668\,\text{s}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"הגובה ברגע הזה", r"משוואת המקום בציר האנכי. התאוצה היא תאוצת הכובד, שלילית", r"y = 0 + 9.42 \cdot 1.668 + \tfrac{1}{2}(-10) \cdot 1.668^2 \approx 15.71 - 13.91 \approx 1.80\,\text{m}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"משווים לגובה השער", r"הגובה חיובי, כלומר הכדור עוד באוויר, והוא נמוך מהמשקוף", r"0 < 1.80\,\text{m} < 2.44\,\text{m}"),
    ], r"$\approx 1.8\,\text{m}$: בין הקרקע למשקוף, ולכן הכדור נכנס", key=r"y=1.8 m"),
    P("ד", r"שחקן אחר בעט מאותו מרחק ובאותה זווית, אבל במהירות התחלתית גדולה מ-$v_0$. האם הכדור נכנס בוודאות לשער? הסבירו בלי לחשב.", choice(["כן", "לא"], 1), ["understanding", "principle"], [
        S(r"מה משתנה", r"עם מהירות גדולה יותר הכדור מגיע לקו השער מוקדם יותר, ולכן לא מספיק לרדת כמו קודם. הוא עלול לחצות את הקו גבוה מהמשקוף", r"v_0\ \uparrow \;\Rightarrow\; t\ \downarrow"),
    ], r"לא: הכדור יגיע לקו השער בגובה אחר, ועלול לעבור מעל השער", key=r"לא"),
  ],
  concepts=["זריקה משופעת", "רכיבי מהירות", "גרף של רכיב אנכי", "גובה בנקודה נתונה"],
  summary=r"בעיטת פננקה: בחירת הגרף הנכון, מה קבוע לאורך המסלול, ובדיקה שהכדור עובר מתחת למשקוף.",
  review="הנחה שלי.\nבמקור סעיף ב הוא (1) ו-(2), וכך גם אצלנו.\nבסעיף ג הוספתי שאלה מספרית, באיזה גובה הכדור חוצה את קו השער, כדי שאפשר יהיה לבדוק את התשובה.\nמה לבדוק: רק לאשר.")
